python3 << 'EOF'
import csv

# Read the file and find Georgia data
georgia_data = {}

with open('weo_data.xls', 'r') as f:
    reader = csv.reader(f, delimiter='\t')
    for row in reader:
        if len(row) > 3 and 'Georgia' in str(row[3]):
            descriptor = str(row[4]) if len(row) > 4 else ''
            if 'Gross domestic product' in descriptor:
                values = {}
                # Years 2020-2027 are in columns 40-47 (0-indexed)
                for i, year in enumerate(range(2020, 2028), 40):
                    if i < len(row) and row[i] and row[i] != 'n/a' and row[i] != '':
                        try:
                            values[year] = float(row[i])
                        except:
                            values[year] = row[i]
                if values:
                    georgia_data[descriptor] = values
                    print(f"\n{descriptor}:")
                    for year, value in values.items():
                        print(f"  {year}: {value}")

# Save the data
import json
with open('georgia_weo_actual.json', 'w') as f:
    json.dump(georgia_data, f, indent=2)

print(f"\n\nSaved {len(georgia_data)} series for Georgia to georgia_weo_actual.json")

EOF

